#!/usr/bin/env node
/**
 * @file pipeline/extract/diagrams.ts
 * @description Generate Mermaid diagrams from codebase structure
 */

import fs from 'fs';
import path from 'path';
import chalk from 'chalk';

interface DomainNode {
  id: string;
  name: string;
  namespace: string;
  pages: string[];
  features: string[];
  state: string[];
  services: string[];
}

function generateDomainDiagram(domains: DomainNode[]): string {
  const lines = [
    '%% Domain Structure Diagram',
    '%% Auto-generated by preflight system',
    '',
    'graph TB',
    '',
  ];

  // Group by namespace
  const namespaces = new Map<string, DomainNode[]>();
  for (const domain of domains) {
    const list = namespaces.get(domain.namespace) || [];
    list.push(domain);
    namespaces.set(domain.namespace, list);
  }

  for (const [namespace, domainList] of namespaces) {
    lines.push(`    subgraph ${namespace}["${namespace}"]`);

    for (const domain of domainList) {
      const nodeId = `${namespace}_${domain.name}`.replace(/-/g, '_');
      const label = domain.name;
      lines.push(`        ${nodeId}["${label}"]`);
    }

    lines.push(`    end`);
    lines.push('');
  }

  // Add styling
  lines.push('    classDef domain fill:#1168bd,stroke:#0b4884,color:#fff');

  return lines.join('\n');
}

function generateDataFlowDiagram(domains: DomainNode[]): string {
  const lines = [
    '%% Data Flow Diagram',
    '%% Auto-generated by preflight system',
    '',
    'flowchart LR',
    '',
    '    subgraph Routes["Route Layer"]',
    '        R["Routes<br/>+page.svelte"]',
    '    end',
    '',
    '    subgraph Domains["Domain Layer"]',
  ];

  // Add domain boxes
  for (const domain of domains.slice(0, 5)) { // Limit for readability
    const nodeId = `D_${domain.namespace}_${domain.name}`.replace(/-/g, '_');
    lines.push(`        ${nodeId}["${domain.namespace}/${domain.name}"]`);
  }

  lines.push('    end');
  lines.push('');
  lines.push('    subgraph System["System Layer"]');
  lines.push('        SYS["sys/"]');
  lines.push('        GEN["generated/"]');
  lines.push('    end');
  lines.push('');

  // Add connections
  lines.push('    R --> Domains');
  lines.push('    Domains --> SYS');
  lines.push('    SYS --> GEN');
  lines.push('');

  // Styling
  lines.push('    style R fill:#e1f5fe,stroke:#0288d1');
  lines.push('    style Domains fill:#e8f5e9,stroke:#388e3c');
  lines.push('    style System fill:#fff3e0,stroke:#f57c00');

  return lines.join('\n');
}

function generateDependencyDiagram(domains: DomainNode[]): string {
  const lines = [
    '%% Domain Dependency Diagram',
    '%% Auto-generated by preflight system',
    '',
    'graph LR',
    '',
  ];

  // Create nodes
  for (const domain of domains) {
    const nodeId = `${domain.namespace}_${domain.name}`.replace(/-/g, '_');
    lines.push(`    ${nodeId}["${domain.namespace}/${domain.name}"]`);
  }

  lines.push('');

  // Note: Real dependencies would be extracted from imports
  // This is a placeholder structure
  lines.push('    %% Dependencies would be extracted from actual imports');
  lines.push('    %% Add connections like: domain_a --> domain_b');

  return lines.join('\n');
}

async function main() {
  const platformRoot = path.resolve(__dirname, '../../..');
  const scanPath = path.join(platformRoot, '.doc-scan.json');

  console.log('');
  console.log(chalk.bold.cyan('DevPulse Diagram Generator'));
  console.log('');

  // Load scan results
  if (!fs.existsSync(scanPath)) {
    console.error(chalk.red('Error: No scan results found. Run `pnpm docs:scan` first.'));
    process.exit(1);
  }

  const scan = JSON.parse(fs.readFileSync(scanPath, 'utf-8'));
  const domains: DomainNode[] = scan.domains.map((d: any) => ({
    id: `${d.namespace}_${d.name}`,
    name: d.name,
    namespace: d.namespace,
    pages: d.pages || [],
    features: d.features || [],
    state: d.state || [],
    services: d.services || [],
  }));

  console.log(chalk.dim(`Found ${domains.length} domains`));

  // Generate diagrams
  const diagramsDir = path.join(platformRoot, scan.targetRoot, 'docs/diagrams/generated');

  if (!fs.existsSync(diagramsDir)) {
    fs.mkdirSync(diagramsDir, { recursive: true });
  }

  // Domain structure diagram
  const domainDiagram = generateDomainDiagram(domains);
  fs.writeFileSync(path.join(diagramsDir, 'domain-structure.mmd'), domainDiagram);
  console.log(chalk.green('  ✓ Generated domain-structure.mmd'));

  // Data flow diagram
  const flowDiagram = generateDataFlowDiagram(domains);
  fs.writeFileSync(path.join(diagramsDir, 'data-flow.mmd'), flowDiagram);
  console.log(chalk.green('  ✓ Generated data-flow.mmd'));

  // Dependency diagram
  const depDiagram = generateDependencyDiagram(domains);
  fs.writeFileSync(path.join(diagramsDir, 'dependencies.mmd'), depDiagram);
  console.log(chalk.green('  ✓ Generated dependencies.mmd'));

  console.log('');
  console.log(chalk.dim(`Diagrams written to ${diagramsDir}`));
  console.log('');
}

main().catch(err => {
  console.error(chalk.red('Diagram generation error:'), err);
  process.exit(1);
});
